using TMPro;
using UnityEngine;

namespace ArcaneKeepers.Tutorial
{
    /// <summary>
    /// Every piece of art, font, colour and (optional) sound the tutorial uses, in one asset
    /// (Assets/UserInterface/Tutorial/Data/TutorialTheme.asset) so it can be re-skinned without touching code.
    /// The sprites are generated by Assets/UserInterface/Tutorial/Tools/GenerateTutorialArt.py.
    /// </summary>
    [CreateAssetMenu(menuName = "Arcane Keepers/Tutorial Theme", fileName = "TutorialTheme")]
    public class TutorialTheme : ScriptableObject
    {
        [Header("Text")]
        public TMP_FontAsset font;
        [Tooltip("Outlined material for HUD labels (wave meter, skip button)")]
        public Material chunkyMaterial;

        [Header("Dog_Hero")]
        public Sprite dog;
        public Sprite dogShadow;

        [Header("Speech bubble")]
        public Sprite bubble;
        public Sprite bubbleShadow;
        public Sprite bubbleTail;
        public Sprite nextArrow;

        [Header("Pointer + highlights")]
        public Sprite wand;
        [Tooltip("Where the wand's crystal sits in the wand sprite (0-1)")]
        public Vector2 wandTip = new Vector2(0.492f, 0.85f);
        [Tooltip("Glow + sparkle trail colour around the wand's crystal")]
        public Color wandGlow = new Color32(150, 236, 255, 255);
        public Sprite glowFrame;
        public Sprite tileGlow;
        public Sprite spotHole;
        public Sprite chevron;

        [Header("Emotes")]
        public Sprite emoteExclaim;
        public Sprite emoteQuestion;
        public Sprite emoteHeart;
        public Sprite emoteSweat;
        public Sprite emoteSparkle;

        [Header("HUD")]
        public Sprite meterBack;
        public Sprite meterFill;
        public Sprite skullToken;
        public Sprite waveFlag;
        public Sprite skipButton;

        [Header("FX")]
        public Sprite softGlow;
        public Sprite sparkle;
        public Sprite ring;
        public Sprite puff;
        public Sprite starChunk;

        [Header("Colours")]
        public Color ink = new Color32(29, 21, 51, 255);
        public Color cream = new Color32(255, 244, 222, 255);
        public Color gold = new Color32(255, 200, 60, 255);
        public Color danger = new Color32(236, 62, 56, 255);
        [Tooltip("Keyword colour inside the speech bubble")]
        public Color keyword = new Color32(36, 104, 222, 255);

        [Header("Sound (optional, leave empty for silence)")]
        public AudioClip popSound;
        public AudioClip talkBlip;
        public AudioClip cheerSound;
        [Range(0f, 1f)] public float volume = 0.7f;
    }
}
